<script setup lang="ts">
import{computed,ref}from'vue';import{basemapDefinitions,type BasemapId}from'../config/basemaps.config';import type{TrafficLayerDefinition,TrafficLayerStyle}from'../types';import type{VectorLayerRecord}from'../vector/VectorLayerStore';import type{SpatialAssetRecord,SpatialAssetType}from'../assets/SpatialAssetStore';
const props=defineProps<{open:boolean;activeBasemap:BasemapId;layers:TrafficLayerDefinition[];visibleIds:string[];vectorLayers:VectorLayerRecord[];assets:SpatialAssetRecord[];loading:boolean}>();const emit=defineEmits<{close:[];basemapChange:[BasemapId];layerToggle:[string,boolean];layerStyle:[string,Partial<TrafficLayerStyle>];vectorUpload:[File];vectorToggle:[string,boolean];vectorRemove:[string];vectorLocate:[string];vectorStyle:[string,Partial<TrafficLayerStyle>];assetAdd:[{name:string;type:SpatialAssetType;url:string}];assetToggle:[string,boolean];assetRemove:[string];assetLocate:[string];refresh:[]}>();
type Tab='basemap'|'vector'|'assets'|'business';const tab=ref<Tab>('basemap');const assetName=ref('');const assetUrl=ref('');const assetType=ref<SpatialAssetType>('imagery');const tabTitle=computed(()=>({basemap:'基础地图',vector:'矢量数据',assets:'空间资源',business:'业务图层'}[tab.value]));const tabDesc=computed(()=>({basemap:'选择地图默认背景影像',vector:'上传 GeoJSON 并配置显示样式',assets:'管理本地影像、地形、倾斜摄影与点云',business:'管理真实 SHP 和数据库业务图层'}[tab.value]));function upload(e:Event){const input=e.target as HTMLInputElement;const file=input.files?.[0];if(file)emit('vectorUpload',file);input.value=''}function addAsset(){if(!assetName.value.trim()||!assetUrl.value.trim())return;emit('assetAdd',{name:assetName.value.trim(),type:assetType.value,url:assetUrl.value.trim()});assetName.value='';assetUrl.value=''}
</script>
<template><aside v-if="open" class="admin"><header><div><b>地图资源配置后台</b><small>统一管理底图、矢量、切片、地形与业务图层</small></div><button class="back" @click="$emit('close')">← 返回地图</button></header><div class="workspace"><nav><button :class="{active:tab==='basemap'}" @click="tab='basemap'"><i>01</i><span>基础地图<small>街道、卫星、浅色</small></span></button><button :class="{active:tab==='vector'}" @click="tab='vector'"><i>02</i><span>矢量数据<small>上传与样式配置</small></span><em>{{vectorLayers.length}}</em></button><button :class="{active:tab==='assets'}" @click="tab='assets'"><i>03</i><span>空间资源<small>影像、地形、三维</small></span><em>{{assets.length}}</em></button><button :class="{active:tab==='business'}" @click="tab='business'"><i>04</i><span>业务图层<small>SHP 与数据库图层</small></span><em>{{layers.length}}</em></button></nav><main><div class="page-title"><div><h2>{{tabTitle}}</h2><p>{{tabDesc}}</p></div><label v-if="tab==='vector'" class="primary">＋ 上传 GeoJSON<input type="file" accept=".geojson,.json" @change="upload"></label><button v-if="tab==='business'" class="primary" :disabled="loading" @click="$emit('refresh')">刷新数据</button></div>

<section v-if="tab==='basemap'" class="cards basemap-grid"><label v-for="item in basemapDefinitions" :key="item.id" class="basemap-card" :class="{selected:activeBasemap===item.id}"><input type="radio" name="basemap" :checked="activeBasemap===item.id" @change="$emit('basemapChange',item.id)"><div class="preview" :class="`preview--${item.id}`"><span>{{activeBasemap===item.id?'当前使用':'选择底图'}}</span></div><div class="card-body"><i></i><span><b>{{item.name}}</b><small>{{item.description}}</small></span></div></label></section>

<section v-else-if="tab==='vector'"><div v-if="!vectorLayers.length" class="empty"><b>还没有矢量图层</b><span>点击右上角上传 WGS84 GeoJSON 点、线或面文件</span></div><article v-for="item in vectorLayers" :key="item.id" class="config-card"><div class="card-head"><label class="switch-row"><input type="checkbox" :checked="item.visible" @change="$emit('vectorToggle',item.id,($event.target as HTMLInputElement).checked)"><i></i><span><b>{{item.name}}</b><small>{{item.features.length}} 个要素 · {{item.definition.geometryType}}</small></span></label><div class="actions"><button @click="$emit('vectorLocate',item.id)">定位</button><button class="danger" @click="$emit('vectorRemove',item.id)">删除</button></div></div><div class="form-grid"><label>图形颜色<input type="color" :value="item.definition.style.color" @input="$emit('vectorStyle',item.id,{color:($event.target as HTMLInputElement).value})"></label><label>{{item.definition.geometryType==='point'?'点大小':'线宽'}}<input type="number" min="1" max="30" :value="item.definition.style.width||4" @change="$emit('vectorStyle',item.id,{width:Number(($event.target as HTMLInputElement).value)})"></label><label v-if="item.definition.geometryType==='point'" class="checkbox">显示文字<input type="checkbox" :checked="item.definition.style.showLabel!==false" @change="$emit('vectorStyle',item.id,{showLabel:($event.target as HTMLInputElement).checked})"></label><label v-if="item.definition.geometryType==='point'">文字颜色<input type="color" :value="item.definition.style.labelColor||'#ffffff'" @input="$emit('vectorStyle',item.id,{labelColor:($event.target as HTMLInputElement).value})"></label></div></article></section>

<section v-else-if="tab==='assets'"><article class="form-card"><h3>新增空间资源</h3><p>资源需通过 HTTP 服务访问；3D Tiles 使用 tileset.json。</p><div class="asset-form"><label>资源名称<input v-model="assetName" placeholder="例如：项目倾斜摄影"></label><label>资源类型<select v-model="assetType"><option value="imagery">影像切片 XYZ</option><option value="terrain">Cesium 地形</option><option value="tileset">倾斜摄影 / b3dm</option><option value="pointcloud">点云 3D Tiles</option></select></label><label class="wide">资源地址<input v-model="assetUrl" placeholder="http://127.0.0.1:9000/model/tileset.json"></label><button class="primary wide" @click="addAsset">添加资源</button></div></article><div v-if="!assets.length" class="empty compact"><b>暂无空间资源</b><span>填写上面的地址后添加</span></div><article v-for="asset in assets" :key="asset.id" class="resource-row"><label class="switch-row"><input type="checkbox" :checked="asset.visible" @change="$emit('assetToggle',asset.id,($event.target as HTMLInputElement).checked)"><i></i><span><b>{{asset.name}}</b><small>{{asset.type}} · {{asset.url}}</small></span></label><div class="actions"><button @click="$emit('assetLocate',asset.id)">定位</button><button class="danger" @click="$emit('assetRemove',asset.id)">删除</button></div></article></section>

<section v-else><div class="summary"><span><b>{{layers.length}}</b>图层总数</span><span><b>{{visibleIds.length}}</b>当前显示</span><span><b>{{layers.reduce((n,l)=>n+(l.featureCount||0),0)}}</b>空间要素</span></div><article v-for="layer in layers" :key="layer.id" class="config-card"><div class="card-head"><label class="switch-row"><input type="checkbox" :checked="visibleIds.includes(layer.id)" @change="$emit('layerToggle',layer.id,($event.target as HTMLInputElement).checked)"><i :style="{background:layer.style.color}"></i><span><b>{{layer.name}}</b><small>{{layer.featureCount||0}} 个要素 · {{layer.geometryType}}</small></span></label></div><div class="form-grid business-form"><label>材质颜色<input type="color" :value="layer.style.color" @input="$emit('layerStyle',layer.id,{color:($event.target as HTMLInputElement).value})"></label><label>{{layer.geometryType==='point'?'点径':'线宽'}}<input type="number" min="1" max="30" :value="layer.style.width||4" @change="$emit('layerStyle',layer.id,{width:Number(($event.target as HTMLInputElement).value)})"></label><label v-if="layer.geometryType==='polygon'">填充透明度<input type="number" min="0" max=".8" step=".05" :value="layer.style.opacity??.15" @change="$emit('layerStyle',layer.id,{opacity:Number(($event.target as HTMLInputElement).value)})"></label><label class="checkbox">显示标签<input type="checkbox" :checked="layer.style.showLabel!==false" @change="$emit('layerStyle',layer.id,{showLabel:($event.target as HTMLInputElement).checked})"></label><label>标签字段<select :value="layer.style.labelField||'__layerName'" @change="$emit('layerStyle',layer.id,{labelField:($event.target as HTMLSelectElement).value})"><option value="__layerName">图层名称</option><option v-for="field in layer.fields" :key="field" :value="field">{{field}}</option></select></label><label>标签字号<input type="number" min="10" max="28" :value="layer.style.labelSize||12" @change="$emit('layerStyle',layer.id,{labelSize:Number(($event.target as HTMLInputElement).value)})"></label><label>标签颜色<input type="color" :value="layer.style.labelColor||'#ffffff'" @input="$emit('layerStyle',layer.id,{labelColor:($event.target as HTMLInputElement).value})"></label></div></article></section></main></div><footer><span></span>{{loading?'数据加载中…':'所有配置已保存到本机'}}</footer></aside></template>
<style scoped>.admin{position:absolute;inset:0;z-index:30;display:grid;grid-template-rows:68px 1fr 38px;background:#f3f6f8;color:#263d4c;font-family:"Microsoft YaHei",sans-serif}.admin>header{display:flex;align-items:center;justify-content:space-between;padding:0 28px;background:#fff;border-bottom:1px solid #dce5eb}.admin>header b,.admin>header small{display:block}.admin>header b{font-size:17px}.admin>header small{margin-top:4px;color:#8294a1;font-size:11px}.admin button,.primary{cursor:pointer;border:1px solid #c8d6df;background:#fff;color:#42647a;padding:7px 13px}.admin button:hover{border-color:#14aaca;color:#0787a2}.back{border-color:#9fc8d5!important}.workspace{min-height:0;display:grid;grid-template-columns:220px 1fr}.workspace>nav{padding:18px 12px;background:#102a3a}.workspace>nav button{width:100%;display:flex;align-items:center;gap:10px;margin-bottom:7px;padding:12px;border:0;background:transparent;color:#bad0dc;text-align:left}.workspace>nav button.active{background:#1c4558;color:#fff;border-left:3px solid #23c7e8}.workspace>nav i{font-style:normal;font-size:10px;color:#42cde9}.workspace>nav span{flex:1}.workspace>nav span,.workspace>nav small{display:block}.workspace>nav small{margin-top:3px;color:#789bad;font-size:9px}.workspace>nav em{font-style:normal;font-size:10px;background:#294c5d;padding:2px 6px;border-radius:10px}.workspace>main{min-width:0;overflow:auto;padding:24px 30px}.page-title{display:flex;align-items:center;justify-content:space-between;margin-bottom:20px}.page-title h2{margin:0;font-size:19px}.page-title p{margin:5px 0 0;color:#7d909c;font-size:11px}.primary{background:#0b9fbe!important;border-color:#0b9fbe!important;color:#fff!important}.primary input{display:none}.cards{display:grid;gap:16px}.basemap-grid{grid-template-columns:repeat(3,minmax(180px,1fr))}.basemap-card{overflow:hidden;background:#fff;border:1px solid #d9e3e9;cursor:pointer}.basemap-card.selected{border-color:#12b4d4;box-shadow:0 0 0 2px rgba(18,180,212,.12)}.basemap-card>input{display:none}.preview{height:140px;display:flex;align-items:flex-end;padding:10px;box-sizing:border-box;background:linear-gradient(135deg,#a7c5d5,#eef4f7)}.preview--satellite{background:linear-gradient(135deg,#2d543e,#9c8e65)}.preview--dark{background:linear-gradient(135deg,#102b3b,#305264)}.preview span{font-size:10px;color:#fff;background:rgba(0,0,0,.45);padding:4px 7px}.card-body{display:flex;align-items:center;gap:9px;padding:14px}.card-body i{width:12px;height:12px;border:1px solid #8da2ae;border-radius:50%}.selected .card-body i{border:4px solid #12b4d4;width:6px;height:6px}.card-body span,.card-body b,.card-body small{display:block}.card-body small{margin-top:4px;color:#8295a0;font-size:10px}.config-card,.form-card,.resource-row,.summary{margin-bottom:12px;padding:16px 18px;background:#fff;border:1px solid #dce5ea}.card-head,.resource-row{display:flex;align-items:center;justify-content:space-between}.switch-row{display:flex;align-items:center;gap:10px;min-width:0}.switch-row>input{display:none}.switch-row>i{width:10px;height:10px;background:#18b8d4;box-shadow:0 0 0 4px #e3f7fa}.switch-row:has(input:not(:checked)){opacity:.55}.switch-row span,.switch-row b,.switch-row small{display:block}.switch-row small{margin-top:4px;color:#8497a3;font-size:10px;max-width:620px;overflow:hidden;text-overflow:ellipsis}.actions{display:flex;gap:6px}.danger{color:#d65b5b!important}.form-grid{display:grid;grid-template-columns:repeat(4,minmax(120px,1fr));gap:12px;margin-top:15px;padding-top:14px;border-top:1px solid #edf1f3}.form-grid label,.asset-form label{font-size:11px;color:#607887}.form-grid input:not([type=checkbox]),.form-grid select,.asset-form input,.asset-form select{box-sizing:border-box;width:100%;height:32px;margin-top:6px;padding:5px 8px;border:1px solid #cbd8df;background:#fff;color:#29485a}.form-grid input[type=color]{padding:2px}.checkbox{display:flex;align-items:center;gap:8px;padding-top:20px}.checkbox input{order:-1}.form-card h3{margin:0;font-size:14px}.form-card p{color:#7e929e;font-size:10px}.asset-form{display:grid;grid-template-columns:1fr 1fr;gap:13px;margin-top:16px}.asset-form .wide{grid-column:1/-1}.empty{display:grid;place-items:center;min-height:220px;background:#fff;border:1px dashed #c9d9e1;color:#7e929e}.empty b,.empty span{display:block}.empty b{margin-bottom:-70px;color:#3e596a}.empty.compact{min-height:90px;margin-bottom:12px}.empty.compact b{margin-bottom:-18px}.summary{display:flex;gap:40px}.summary span{font-size:11px;color:#758b98}.summary b{margin-right:6px;font-size:20px;color:#0a9dbd}.admin>footer{padding:11px 28px;background:#fff;border-top:1px solid #dce5eb;color:#788d99;font-size:10px}.admin>footer span{display:inline-block;width:7px;height:7px;margin-right:7px;border-radius:50%;background:#28c885}@media(max-width:900px){.workspace{grid-template-columns:170px 1fr}.basemap-grid{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr 1fr}.workspace>main{padding:18px}.preview{height:90px}}</style>
